{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "Section",
    "displayName": "Section",
    "group": "Layout",
    "category": "Layout",
    "keywords": [
      "section",
      "panel",
      "container",
      "group",
      "fieldset",
      "region",
      "block"
    ],
    "props": [
      {
        "name": "variant",
        "type": "'section' | 'transparent' | 'muted'",
        "description": "Background variant applied to the section container.",
        "default": "'section'"
      },
      {
        "name": "width",
        "type": "SizeValue",
        "description": "Width of the section; a number is interpreted as pixels, a string is used as-is."
      },
      {
        "name": "height",
        "type": "SizeValue",
        "description": "Height of the section; a number is interpreted as pixels, a string is used as-is."
      },
      {
        "name": "maxWidth",
        "type": "SizeValue",
        "description": "Maximum width of the section."
      },
      {
        "name": "minHeight",
        "type": "SizeValue",
        "description": "Minimum height of the section."
      },
      {
        "name": "children",
        "type": "ReactNode",
        "description": "Content rendered inside the section."
      },
      {
        "name": "dividers",
        "type": "Array<'top' | 'bottom' | 'start' | 'end'>",
        "description": "Which sides of the section have divider borders."
      },
      {
        "name": "padding",
        "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
        "description": "Internal padding using the spacing scale (0, 0.5, 1, 1.5, 2, 3, 4, 5, 6, 8, 10). Use padding={0} for edge-to-edge content.",
        "default": "4"
      },
      {
        "name": "paddingInline",
        "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
        "description": "Inline (horizontal) padding override. Overrides only the inline-axis padding while preserving block padding from `padding` or the container theme default. Accepts the spacing scale (0, 0.5, 1, 1.5, 2, 3, 4, 5, 6, 8, 10)."
      },
      {
        "name": "paddingInlineStart",
        "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
        "description": "Inline-start padding override (left in LTR, right in RTL). Overrides paddingInline and padding on that edge only."
      },
      {
        "name": "paddingInlineEnd",
        "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
        "description": "Inline-end padding override (right in LTR, left in RTL). Overrides paddingInline and padding on that edge only."
      },
      {
        "name": "paddingBlock",
        "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
        "description": "Block (vertical) padding override. Overrides only the block-axis padding while preserving inline padding from `padding` or the container theme default. Accepts the spacing scale (0, 0.5, 1, 1.5, 2, 3, 4, 5, 6, 8, 10)."
      },
      {
        "name": "paddingBlockStart",
        "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
        "description": "Block-start (top) padding, using the spacing scale. Overrides paddingBlock and padding on that edge only."
      },
      {
        "name": "paddingBlockEnd",
        "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
        "description": "Block-end (bottom) padding, using the spacing scale. Overrides paddingBlock and padding on that edge only."
      },
      {
        "name": "xstyle",
        "type": "StyleXStyles",
        "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value, not an inline style object."
      }
    ],
    "theming": {
      "container": true,
      "targets": [
        {
          "className": "astryx-section",
          "visualProps": [
            "variant"
          ]
        }
      ],
      "derived": [
        {
          "property": "padding",
          "expand": "container"
        }
      ]
    },
    "usage": {
      "anatomy": [
        {
          "name": "Section container",
          "required": true,
          "description": "Painted container that groups a page region."
        },
        {
          "name": "Consumer content",
          "required": false,
          "description": "Caller-provided content rendered inside the section container."
        }
      ],
      "description": "Section is the correct way to create page regions and group related content on a page. Use it for settings groups, form sections, sidebar areas, or any time you need visual separation between parts of a page. If you are tempted to use a Card for a page section, use Section instead.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Use Section for page-level grouping: settings panels, form groups, sidebar regions. These are sections of a page, not discrete items."
        },
        {
          "guidance": true,
          "description": "Start with the default variant. Use muted only to call attention to a specific region."
        },
        {
          "guidance": true,
          "description": "Add dividers between same-background sections that need separation."
        },
        {
          "guidance": true,
          "description": "Combine with a heading + Stack for a typical page section pattern."
        },
        {
          "guidance": false,
          "description": "Use Card when you mean Section. Cards are for discrete items (one notification, one profile). Sections are for page regions."
        },
        {
          "guidance": true,
          "description": "To center a Section, set marginInlineStart and marginInlineEnd to 'auto' in xstyle. If Astryx source is compiled in your app's own StyleX pass, the marginInline shorthand loses to Section's own inline margins."
        }
      ]
    },
    "examples": [
      {
        "label": "Center a Section with a maximum width",
        "code": "import * as stylex from '@stylexjs/stylex';\nimport {Section} from '@astryxdesign/core/Section';\n\nconst styles = stylex.create({\n  centered: {marginInlineStart: 'auto', marginInlineEnd: 'auto'},\n});\n\nfunction Page({children}: {children: React.ReactNode}) {\n  return (\n    <Section maxWidth={1280} xstyle={styles.centered}>\n      {children}\n    </Section>\n  );\n}"
      }
    ],
    "package": "@astryxdesign/core",
    "import": "@astryxdesign/core/Section",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
